export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/tilecov
mkdir -p $D && cd $D || exit 1
cat > /tmp/tc.b64 <<'B64EOF'

B64EOF
rm -rf ./* && base64 -d /tmp/tc.b64 > /tmp/tc.zip && unzip -oq /tmp/tc.zip -d .
/opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source ./build.tcl > build.log 2>&1
if grep -q COV_DONE build.log; then echo BUILD_OK; grep -E 'SITES=|PLACED_CONSTRAINTS=' build.log; else echo BUILD_FAIL; grep -E 'ERROR|SITES=' build.log | head -5; fi
tar czf /tmp/tilecov_out.tgz cov.bit cov.pips build.log 2>/dev/null; echo TAR_DONE